1	//! MPSC ring: multi-producer single-consumer sibling of the
2	//! SPSC ring, per the design doc's "MPSC ring (sibling
3	//! primitive)" section:
4	//!
5	//! - Same region shape as the SPSC ring — a four-line
6	//!   [`MpscHeader`] then slots — plus a per-slot sequence
7	//!   array between them: `seq[pos]` publishes each slot
8	//!   independently, because claim order and commit order
9	//!   differ under concurrent producers.
10	//! - Producers CAS-claim `producer_idx`; the consumer stays
11	//!   CAS-free. Fullness is read from the slot seq, so
12	//!   producers never load `consumer_idx`.
13	//! - `capacity` is at least 2: committed is Vyukov's `pos + 1`
14	//!   and released `pos + M`, the same value at `M = 1`, where
15	//!   both sides misread the slot and spin forever. `init` and
16	//!   `attach` reject it, and `mpsc::v1` runs down to 1.
17	//! - Own magic and layout version: a region is one kind or
18	//!   the other, and cross-attaching fails toward
19	//!   [`Error::BadMagic`].
20	//! - The claim CAS raises the atomic floor for MPSC users
21	//!   only — this module is gated on `target_has_atomic =
22	//!   "32"`; the SPSC ring stays load/store-only.
23	
24	use core::marker::PhantomData;
25	use core::mem::size_of;
26	use core::sync::atomic::{AtomicU32, Ordering};
27	
28	use crate::{CACHE_LINE_SIZE, CacheAligned, Error, USER_WORDS};
29	
30	mod consumer;
31	mod producer;
32	
33	pub use consumer::{MpscConsumer, MpscReadSlot};
34	pub use producer::MpscProducer;
35	
36	/// Layout marker written by [`MpscRing::init`]; distinct from
37	/// the SPSC magic so cross-kind attach fails toward
38	/// [`Error::BadMagic`].
39	const MPSC_MAGIC: u32 = 0x5A43_4D31; // "ZCM1"
40	
41	/// Bumped on any change to the MPSC region layout;
42	/// independent of the SPSC layout version.
43	const MPSC_LAYOUT_VERSION: u32 = 1;
44	
45	/// Capacity bound: `2^30`, not the SPSC `2^31` — the seq
46	/// tombstone encoding reserves index-arithmetic headroom (see
47	/// the design doc's "MPSC open questions").
48	const MPSC_MAX_CAPACITY: u32 = 1 << 30;
49	
50	/// Capacity floor: at 1 the committed and released seq values
51	/// coincide and the ring wedges (see the module doc), so v0
52	/// refuses it rather than hang.
53	const MPSC_MIN_CAPACITY: u32 = 2;
54	
55	/// Tombstone offset: an unwound `send_with` commits
56	/// `pos + 1 + TOMBSTONE` instead of `pos + 1`, marking a
57	/// claimed slot the consumer must release without delivering.
58	///
59	/// - Unambiguous at both wait points: the consumer at `c`
60	///   legitimately sees only `seq - (c+1)` of `-1` (not yet
61	///   committed) or `0` (committed), so exactly `2^31` means
62	///   tombstone; a producer's wrapping-signed diff reads a
63	///   tombstoned previous lap as negative — "full" — until the
64	///   consumer skips it, which is the correct backpressure.
65	pub(crate) const TOMBSTONE: u32 = 1 << 31;
66	
67	/// Control block at offset 0 of an MPSC region — same
68	/// four-line shape as the SPSC [`Header`](crate::spsc::v0::Header), but
69	/// its own type: the layouts evolve independently and the
70	/// index-ownership story differs.
71	///
72	/// - line 0: geometry, written by [`MpscRing::init`] with
73	///   `magic` last (`Release`), read-only thereafter.
74	/// - line 1: `producer_idx` — CAS-claimed by *all* producers
75	///   (the contended line), never read by the consumer's hot
76	///   path.
77	/// - line 2: `consumer_idx` — written only by the consumer;
78	///   never read by producers (fullness comes from the slot
79	///   seq), so it is resume state and diagnostic occupancy.
80	/// - line 3: `user`, app-owned scratch — same contract as the
81	///   SPSC user line.
82	/// - Every field is atomic: the region may be mapped by a
83	///   peer at any time.
84	#[repr(C)]
85	pub struct MpscHeader {
86	    /// Layout marker ([`MPSC_MAGIC`]); stored last by init
87	    /// (`Release`), loaded first by attach (`Acquire`).
88	    magic: AtomicU32,
89	    /// Layout version ([`MPSC_LAYOUT_VERSION`]).
90	    layout_version: AtomicU32,
91	    /// Slot size N in bytes — a [`CACHE_LINE_SIZE`] multiple.
92	    slot_size: AtomicU32,
93	    /// Slot count M — a power of two `<= 2^30`.
94	    capacity: AtomicU32,
95	    /// [`CACHE_LINE_SIZE`] this region was built with.
96	    cache_line_size: AtomicU32,
97	    /// Free-running count of slot positions claimed by
98	    /// producers (CAS).
99	    producer_idx: CacheAligned<AtomicU32>,
100	    /// Free-running count of messages released; consumer-owned
101	    /// resume state, not read by producers.
102	    consumer_idx: CacheAligned<AtomicU32>,
103	    /// App-owned scratch line ([`USER_WORDS`] words): zeroed by
104	    /// init, then never touched by the crate.
105	    user: CacheAligned<[AtomicU32; USER_WORDS]>,
106	}
107	
108	const _: () = assert!(size_of::<MpscHeader>() == 4 * CACHE_LINE_SIZE);
109	
110	/// A validated view over an MPSC ring region.
111	///
112	/// - Geometry is snapshotted out of the header at init/attach,
113	///   as the SPSC ring does: per-op paths never re-read fields
114	///   a peer could scribble on.
115	/// - Region layout: [`MpscHeader`], the seq array (`M ×
116	///   AtomicU32`, padded up to a cache line), then M slots of N
117	///   bytes.
118	pub struct MpscRing<'a> {
119	    /// The region's control block.
120	    header: &'a MpscHeader,
121	    /// Base of the per-slot sequence array.
122	    seqs: *const AtomicU32,
123	    /// Base of the slot array.
124	    slots: *mut u8,
125	    /// Snapshot of `header.slot_size`.
126	    slot_size: u32,
127	    /// Snapshot of `header.capacity`.
128	    capacity: u32,
129	    /// Slot-position mask (`capacity - 1`).
130	    mask: u32,
131	    _region: PhantomData<&'a [u8]>,
132	}
133	
134	impl<'a> MpscRing<'a> {
135	    /// Initialize a fresh region and return the ring over it.
136	    ///
137	    /// - `slot_size` — N bytes per slot, a [`CACHE_LINE_SIZE`]
138	    ///   multiple.
139	    /// - `capacity` — M slots, a power of two from 2 to `2^30`.
140	    /// - The region must be [`CACHE_LINE_SIZE`]-aligned and at
141	    ///   least [`mpsc_region_size`] bytes.
142	    pub fn init(region: &'a mut [u8], slot_size: u32, capacity: u32) -> Result<Self, Error> {
143	        validate_mpsc_geometry(slot_size, capacity)?;
144	        let len = region.len();
145	        // Taken exactly once — see `Ring::init` for the Stacked
146	        // Borrows rationale.
147	        let base = region.as_mut_ptr();
148	        let header = mpsc_header_ptr(base, len)?;
149	        if (len as u64) < mpsc_region_size(slot_size, capacity) {
150	            return Err(Error::TooSmall);
151	        }
152	        // SAFETY: alignment + room for the MpscHeader checked
153	        // by mpsc_header_ptr; region is exclusively borrowed
154	        // for 'a; any byte pattern is a valid MpscHeader
155	        // (all-atomic fields, plain-byte padding).
156	        let header = unsafe { &*header };
157	        header
158	            .layout_version
159	            .store(MPSC_LAYOUT_VERSION, Ordering::Relaxed);
160	        header.slot_size.store(slot_size, Ordering::Relaxed);
161	        header.capacity.store(capacity, Ordering::Relaxed);
162	        header
163	            .cache_line_size
164	            .store(CACHE_LINE_SIZE as u32, Ordering::Relaxed);
165	        header.producer_idx.store(0, Ordering::Relaxed);
166	        header.consumer_idx.store(0, Ordering::Relaxed);
167	        for word in header.user.iter() {
168	            word.store(0, Ordering::Relaxed);
169	        }
170	        // SAFETY: in bounds — len covers header + seq array.
171	        let seqs = unsafe { base.add(size_of::<MpscHeader>()) } as *const AtomicU32;
172	        // seq[i] = i marks every slot claimable by the position
173	        // that will first reach it.
174	        for i in 0..capacity {
175	            // SAFETY: i < capacity, inside the seq array
176	            // validated by the region-size check.
177	            unsafe { &*seqs.add(i as usize) }.store(i, Ordering::Relaxed);
178	        }
179	        // Published last: a peer that pre-mapped the region must
180	        // never observe the magic before the geometry and seq
181	        // stores it validates and relies on.
182	        header.magic.store(MPSC_MAGIC, Ordering::Release);
183	        // SAFETY: in bounds — len covers header + seqs + slots.
184	        let slots = unsafe { base.add(slots_offset(capacity)) };
185	        Ok(MpscRing {
186	            header,
187	            seqs,
188	            slots,
189	            slot_size,
190	            capacity,
191	            mask: capacity - 1,
192	            _region: PhantomData,
193	        })
194	    }
195	
196	    /// Attach to a region another process (or an earlier call)
197	    /// already initialized, validating its header.
198	    ///
199	    /// # Safety
200	    ///
201	    /// - `region` points to `len` bytes of memory that outlive
202	    ///   `'a`, genuinely shared and writable (e.g. a
203	    ///   `MAP_SHARED` mapping).
204	    /// - At most one consumer attaches; any number of
205	    ///   producers may (MPSC contract).
206	    pub unsafe fn attach(region: *mut u8, len: usize) -> Result<Self, Error> {
207	        let header = mpsc_header_ptr(region, len)?;
208	        // SAFETY: alignment + room for the MpscHeader checked
209	        // by mpsc_header_ptr; caller guarantees the memory is
210	        // live and shared.
211	        let header = unsafe { &*header };
212	        // Acquire pairs with init's Release store of magic: a
213	        // valid magic means the geometry and seq stores are
214	        // visible.
215	        if header.magic.load(Ordering::Acquire) != MPSC_MAGIC {
216	            return Err(Error::BadMagic);
217	        }
218	        if header.layout_version.load(Ordering::Relaxed) != MPSC_LAYOUT_VERSION {
219	            return Err(Error::BadLayoutVersion);
220	        }
221	        if header.cache_line_size.load(Ordering::Relaxed) != CACHE_LINE_SIZE as u32 {
222	            return Err(Error::BadCacheLine);
223	        }
224	        // Snapshot geometry once; per-op paths never re-read it.
225	        let slot_size = header.slot_size.load(Ordering::Relaxed);
226	        let capacity = header.capacity.load(Ordering::Relaxed);
227	        validate_mpsc_geometry(slot_size, capacity)?;
228	        if (len as u64) < mpsc_region_size(slot_size, capacity) {
229	            return Err(Error::TooSmall);
230	        }
231	        // SAFETY: in bounds — len covers header + seqs + slots.
232	        let seqs = unsafe { region.add(size_of::<MpscHeader>()) } as *const AtomicU32;
233	        // SAFETY: as above.
234	        let slots = unsafe { region.add(slots_offset(capacity)) };
235	        Ok(MpscRing {
236	            header,
237	            seqs,
238	            slots,
239	            slot_size,
240	            capacity,
241	            mask: capacity - 1,
242	            _region: PhantomData,
243	        })
244	    }
245	
246	    /// Split into one producer handle and the consumer handle.
247	    ///
248	    /// - The producer is `Clone`: one clone per producing
249	    ///   thread (MPSC contract). The consumer is unique per
250	    ///   process; cross-process, exactly one consuming process
251	    ///   is the caller's contract (see [`MpscRing::attach`]).
252	    pub fn split(self) -> (MpscProducer<'a>, MpscConsumer<'a>) {
253	        (
254	            MpscProducer::new(
255	                self.header,
256	                self.seqs,
257	                self.slots,
258	                self.slot_size,
259	                self.mask,
260	            ),
261	            MpscConsumer::new(
262	                self.header,
263	                self.seqs,
264	                self.slots,
265	                self.slot_size,
266	                self.capacity,
267	                self.mask,
268	            ),
269	        )
270	    }
271	}
272	
273	/// Validate a region base pointer and cast it to the
274	/// [`MpscHeader`] it must start with; shared by init / attach.
275	///
276	/// - Same split of duties as the SPSC `header_ptr`: alignment
277	///   and header room here, full-geometry length with the
278	///   caller.
279	fn mpsc_header_ptr(base: *mut u8, len: usize) -> Result<*const MpscHeader, Error> {
280	    if !(base as usize).is_multiple_of(CACHE_LINE_SIZE) {
281	        return Err(Error::Misaligned);
282	    }
283	    if len < size_of::<MpscHeader>() {
284	        return Err(Error::TooSmall);
285	    }
286	    Ok(base as *const MpscHeader)
287	}
288	
289	/// Bytes the seq array occupies, padded up to a cache line so
290	/// the slot array behind it stays line-aligned.
291	///
292	/// - u64: `capacity * 4` reaches `2^32` at the `2^30` cap,
293	///   which would wrap a 32-bit usize.
294	fn seq_bytes(capacity: u32) -> u64 {
295	    (capacity as u64 * size_of::<AtomicU32>() as u64).next_multiple_of(CACHE_LINE_SIZE as u64)
296	}
297	
298	/// Byte offset of the slot array: header, then the padded seq
299	/// array.
300	///
301	/// - usize return: callers offset a pointer with it, and only
302	///   after the u64 region-size check has proven the region —
303	///   hence this offset — fits in memory.
304	fn slots_offset(capacity: u32) -> usize {
305	    size_of::<MpscHeader>() + seq_bytes(capacity) as usize
306	}
307	
308	/// Bytes needed for an MPSC region with the given geometry.
309	///
310	/// - Computed in u64 for the same 32-bit wrap reason as the
311	///   SPSC `region_size`.
312	pub fn mpsc_region_size(slot_size: u32, capacity: u32) -> u64 {
313	    size_of::<MpscHeader>() as u64 + seq_bytes(capacity) + slot_size as u64 * capacity as u64
314	}
315	
316	/// Geometry checks for [`MpscRing::init`] / [`MpscRing::attach`].
317	///
318	/// - Slot size as the SPSC ring; capacity additionally capped
319	///   at [`MPSC_MAX_CAPACITY`] for tombstone headroom and floored
320	///   at [`MPSC_MIN_CAPACITY`], where the protocol holds.
321	fn validate_mpsc_geometry(slot_size: u32, capacity: u32) -> Result<(), Error> {
322	    if slot_size == 0 || !(slot_size as usize).is_multiple_of(CACHE_LINE_SIZE) {
323	        return Err(Error::BadSlotSize);
324	    }
325	    if !capacity.is_power_of_two() || !(MPSC_MIN_CAPACITY..=MPSC_MAX_CAPACITY).contains(&capacity) {
326	        return Err(Error::BadCapacity);
327	    }
328	    Ok(())
329	}
