332	mod tests {
333	    use super::*;
334	    use crate::spsc::v2::{Header, Ring};
335	
336	    /// Test region: header + seq line (4 × 4 B padded to 64) +
337	    /// 4 slots × 1 line.
338	    const REGION_BYTES: usize = size_of::<MpscHeader>() + CACHE_LINE_SIZE + (4 * CACHE_LINE_SIZE);
339	
340	    /// Cache-line-aligned backing store for the tests' rings.
341	    #[repr(C, align(64))]
342	    struct Region([u8; REGION_BYTES]);
343	
344	    impl Region {
345	        fn new() -> Self {
346	            Region([0; REGION_BYTES])
347	        }
348	    }
349	
350	    #[test]
351	    fn mpsc_region_size_accounts_for_seq_array() {
352	        // 4 slots: header 256 + seq 16→64 + slots 256 = 576.
353	        assert_eq!(mpsc_region_size(64, 4), 576);
354	        // 32 slots: seq 128 is already a line multiple.
355	        assert_eq!(
356	            mpsc_region_size(64, 32),
357	            (size_of::<MpscHeader>() + 128 + 32 * 64) as u64
358	        );
359	    }
360	
361	    #[test]
362	    fn mpsc_init_rejects_bad_geometry() {
363	        let mut r = Region::new();
364	        assert_eq!(
365	            MpscRing::init(&mut r.0, 63, 4).err().unwrap(),
366	            Error::BadSlotSize
367	        );
368	        assert_eq!(
369	            MpscRing::init(&mut r.0, 0, 4).err().unwrap(),
370	            Error::BadSlotSize
371	        );
372	        assert_eq!(
373	            MpscRing::init(&mut r.0, 64, 3).err().unwrap(),
374	            Error::BadCapacity
375	        );
376	        assert_eq!(
377	            MpscRing::init(&mut r.0, 64, 0).err().unwrap(),
378	            Error::BadCapacity
379	        );
380	        // Over the MPSC cap (fine for SPSC): tombstone headroom.
381	        assert_eq!(
382	            MpscRing::init(&mut r.0, 64, 1 << 31).err().unwrap(),
383	            Error::BadCapacity
384	        );
385	        // Under the v0 floor (fine for v1): the protocol wedges
386	        // at capacity 1.
387	        assert_eq!(
388	            MpscRing::init(&mut r.0, 64, 1).err().unwrap(),
389	            Error::BadCapacity
390	        );
391	        assert_eq!(
392	            MpscRing::init(&mut r.0, 64, 8).err().unwrap(),
393	            Error::TooSmall
394	        );
395	        assert_eq!(
396	            MpscRing::init(&mut r.0[1..], 64, 4).err().unwrap(),
397	            Error::Misaligned
398	        );
399	        // 32-bit tripwire, as the SPSC test: N * M wraps a
400	        // 32-bit usize; the u64 region size must still reject.
401	        assert_eq!(
402	            MpscRing::init(&mut r.0, 1 << 26, 1 << 6).err().unwrap(),
403	            Error::TooSmall
404	        );
405	        // An SPSC-sized region (no seq line) is too small here.
406	        let spsc_bytes = size_of::<Header>() + 4 * 64;
407	        assert_eq!(
408	            MpscRing::init(&mut r.0[..spsc_bytes], 64, 4).err().unwrap(),
409	            Error::TooSmall
410	        );
411	    }
