413	    #[test]
414	    fn mpsc_init_seeds_seq_array() {
415	        let mut r = Region::new();
416	        // Dirty the region so the seq stores are observable.
417	        r.0.fill(0xAA);
418	        let ring = MpscRing::init(&mut r.0, 64, 4).unwrap();
419	        for i in 0..4 {
420	            // SAFETY: i < capacity; test mirrors init's bounds.
421	            let seq = unsafe { &*ring.seqs.add(i as usize) };
422	            assert_eq!(seq.load(Ordering::Relaxed), i);
423	        }
424	        assert_eq!(ring.slot_size, 64);
425	        assert_eq!(ring.capacity, 4);
426	        assert_eq!(ring.mask, 3);
427	    }
