429	    #[test]
430	    fn mpsc_attach_validates_header() {
431	        let mut r = Region::new();
432	        // Not initialized yet: magic is zero.
433	        let err = unsafe { MpscRing::attach(r.0.as_mut_ptr(), r.0.len()) }
434	            .err()
435	            .unwrap();
436	        assert_eq!(err, Error::BadMagic);
437	        MpscRing::init(&mut r.0, 64, 4).unwrap();
438	        // Taken once after init: each `as_mut_ptr()` borrows the
439	        // whole region, and a second one would invalidate `ring`'s
440	        // header, which the test goes on to write through.
441	        let (base, len) = (r.0.as_mut_ptr(), r.0.len());
442	        let ring = unsafe { MpscRing::attach(base, len) }.unwrap();
443	        assert_eq!(ring.slot_size, 64);
444	        assert_eq!(ring.capacity, 4);
445	        // A different recorded cache line is rejected.
446	        ring.header.cache_line_size.store(128, Ordering::Relaxed);
447	        let err = unsafe { MpscRing::attach(base, len) }.err().unwrap();
448	        assert_eq!(err, Error::BadCacheLine);
449	        // A recorded capacity under the floor is rejected too,
450	        // so a region another build wrote at 1 is not attached.
451	        ring.header
452	            .cache_line_size
453	            .store(CACHE_LINE_SIZE as u32, Ordering::Relaxed);
454	        ring.header.capacity.store(1, Ordering::Relaxed);
455	        let err = unsafe { MpscRing::attach(base, len) }.err().unwrap();
456	        assert_eq!(err, Error::BadCapacity);
457	    }
