477	    use crate::{Empty, Full};
478	    use zerocopy::{FromBytes, Immutable, IntoBytes, KnownLayout};
479	
480	    /// Test message; two words so a torn write would be
481	    /// visible, `val` doubles as the producer id in threaded
482	    /// tests.
483	    #[derive(FromBytes, IntoBytes, KnownLayout, Immutable, Debug, PartialEq)]
484	    #[repr(C)]
485	    struct Msg {
486	        seq: u64,
487	        val: u64,
488	    }
