490	    #[test]
491	    fn mpsc_roundtrip_full_empty() {
492	        let mut r = Region::new();
493	        let (prod, mut cons) = MpscRing::init(&mut r.0, 64, 4).unwrap().split();
494	
495	        // Empty at start.
496	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
497	
498	        // Fill all 4 slots, then Full on a single probe.
499	        for i in 0..4u64 {
500	            prod.send_with::<Msg>(
501	                |_| false,
502	                |m| {
503	                    m.seq = i;
504	                    m.val = i * 10;
505	                },
506	            )
507	            .unwrap();
508	        }
509	        assert_eq!(
510	            prod.send_with::<Msg>(|_| false, |_| {}).err().unwrap(),
511	            Full
512	        );
513	
514	        // Drain in order; then empty again.
515	        for i in 0..4u64 {
516	            let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
517	            assert_eq!(
518	                *msg,
519	                Msg {
520	                    seq: i,
521	                    val: i * 10
522	                }
523	            );
524	            msg.release();
525	        }
526	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
527	
528	        // One more send lands in the masked-around slot 0.
529	        prod.send_with::<Msg>(
530	            |_| false,
531	            |m| {
532	                m.seq = 4;
533	                m.val = 0;
534	            },
535	        )
536	        .unwrap();
537	        let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
538	        assert_eq!(msg.seq, 4);
539	        msg.release();
540	    }
