542	    #[test]
543	    fn mpsc_policies_count_and_give_up() {
544	        let mut r = Region::new();
545	        let (prod, mut cons) = MpscRing::init(&mut r.0, 64, 4).unwrap().split();
546	
547	        // Empty ring: the consumer's policy sees 0-based
548	        // attempts and its `false` becomes Err(Empty).
549	        let mut seen = Vec::new();
550	        let err = cons
551	            .reserve_slot_with::<Msg>(|attempt| {
552	                seen.push(attempt);
553	                attempt < 2
554	            })
555	            .err()
556	            .unwrap();
557	        assert_eq!(err, Empty);
558	        assert_eq!(seen, [0, 1, 2]);
559	
560	        // Fill the ring: the producer's policy gives up with
561	        // Err(Full), and the failed send has zero footprint —
562	        // the fill closure never ran.
563	        for i in 0..4u64 {
564	            prod.send_with::<Msg>(|_| false, |m| m.seq = i).unwrap();
565	        }
566	        let mut seen = Vec::new();
567	        let err = prod
568	            .send_with::<Msg>(
569	                |attempt| {
570	                    seen.push(attempt);
571	                    attempt < 2
572	                },
573	                |_| panic!("fill ran on a full ring"),
574	            )
575	            .err()
576	            .unwrap();
577	        assert_eq!(err, Full);
578	        assert_eq!(seen, [0, 1, 2]);
579	
580	        // With room / messages available the policy is never
581	        // consulted.
582	        let msg = cons
583	            .reserve_slot_with::<Msg>(|_| panic!("policy consulted with a message available"))
584	            .unwrap();
585	        assert_eq!(msg.seq, 0);
586	        msg.release();
587	        prod.send_with::<Msg>(
588	            |_| panic!("policy consulted with room available"),
589	            |m| m.seq = 4,
590	        )
591	        .unwrap();
592	    }
593	
594	    #[test]
595	    // Dropping the guard is the behavior under test.
596	    #[allow(clippy::drop_non_drop)]
597	    fn mpsc_abandoned_read_guard_redelivers() {
598	        let mut r = Region::new();
599	        let (prod, mut cons) = MpscRing::init(&mut r.0, 64, 4).unwrap().split();
600	
601	        prod.send_with::<Msg>(|_| false, |m| m.seq = 1).unwrap();
602	        let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
603	        assert_eq!(msg.seq, 1);
604	        drop(msg);
605	        let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
606	        assert_eq!(msg.seq, 1);
607	        msg.release();
608	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
609	    }
610	
611	    #[test]
612	    fn mpsc_panicking_fill_tombstones_and_skips() {
613	        let mut r = Region::new();
614	        let (prod, mut cons) = MpscRing::init(&mut r.0, 64, 4).unwrap().split();
615	
616	        // A committed message, a panicked fill, another
617	        // committed message.
618	        prod.send_with::<Msg>(|_| false, |m| m.seq = 1).unwrap();
619	        let unwound = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
620	            prod.send_with::<Msg>(
621	                |_| false,
622	                |m| {
623	                    m.seq = 99; // partially filled, then…
624	                    panic!("fill panics");
625	                },
626	            )
627	        }));
628	        assert!(unwound.is_err());
629	        prod.send_with::<Msg>(|_| false, |m| m.seq = 2).unwrap();
630	
631	        // The consumer sees 1 then 2; the tombstoned slot is
632	        // released without delivery.
633	        let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
634	        assert_eq!(msg.seq, 1);
635	        msg.release();
636	        let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
637	        assert_eq!(msg.seq, 2);
638	        msg.release();
639	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
640	
641	        // The skipped slot is claimable again: a full lap
642	        // still fits 4 messages.
643	        for i in 3..7u64 {
644	            prod.send_with::<Msg>(|_| false, |m| m.seq = i).unwrap();
645	        }
646	        assert!(prod.send_with::<Msg>(|_| false, |_| {}).is_err());
647	        for i in 3..7u64 {
648	            let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
649	            assert_eq!(msg.seq, i);
650	            msg.release();
651	        }
652	    }
653	
654	    #[test]
655	    fn mpsc_indices_survive_u32_wrap() {
656	        let mut r = Region::new();
657	        let ring = MpscRing::init(&mut r.0, 64, 4).unwrap();
658	        // Simulate a long-running ring two commits shy of the
659	        // u32 wrap: indices at MAX-1, and each slot's seq must
660	        // equal the free-running position that will next claim
661	        // it (positions MAX-1, MAX, 0, 1 → slots 2, 3, 0, 1).
662	        let start = u32::MAX - 1;
663	        ring.header.producer_idx.store(start, Ordering::Relaxed);
664	        ring.header.consumer_idx.store(start, Ordering::Relaxed);
665	        for (slot, pos) in [(2u32, u32::MAX - 1), (3, u32::MAX), (0, 0), (1, 1)] {
666	            // SAFETY: slot < capacity; test mirrors init.
667	            unsafe { &*ring.seqs.add(slot as usize) }.store(pos, Ordering::Relaxed);
668	        }
669	        let (prod, mut cons) = ring.split();
670	
671	        // Fill across the wrap, then Full.
672	        for i in 0..4u64 {
673	            prod.send_with::<Msg>(|_| false, |m| m.seq = i).unwrap();
674	        }
675	        assert!(prod.send_with::<Msg>(|_| false, |_| {}).is_err());
676	
677	        // Drain in order across the wrap.
678	        for i in 0..4u64 {
679	            let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
680	            assert_eq!(msg.seq, i);
681	            msg.release();
682	        }
683	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
684	    }
