686	    #[test]
687	    fn threaded_mpsc_two_producers() {
688	        // Reduced under Miri: interpreted spin loops are slow.
689	        const COUNT: u64 = if cfg!(miri) { 100 } else { 50_000 };
690	        const PRODUCERS: u64 = 2;
691	        let mut r = Region::new();
692	        let (prod, mut cons) = MpscRing::init(&mut r.0, 64, 4).unwrap().split();
693	
694	        std::thread::scope(|s| {
695	            for p in 0..PRODUCERS {
696	                let prod = prod.clone();
697	                s.spawn(move || {
698	                    for i in 0..COUNT {
699	                        prod.send_with::<Msg>(crate::policy::spin, |m| {
700	                            m.seq = i;
701	                            m.val = p;
702	                        })
703	                        .unwrap(); // OK: policy::spin never gives up
704	                    }
705	                });
706	            }
707	            s.spawn(move || {
708	                // Global arrival order is claim order; only
709	                // per-producer FIFO is promised.
710	                let mut next = [0u64; PRODUCERS as usize];
711	                for _ in 0..PRODUCERS * COUNT {
712	                    let msg = cons.reserve_slot_with::<Msg>(crate::policy::spin).unwrap(); // OK: policy::spin never gives up
713	                    let p = msg.val as usize;
714	                    assert_eq!(msg.seq, next[p], "per-producer order broken");
715	                    next[p] += 1;
716	                    msg.release();
717	                }
718	                assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
719	            });
720	        });
721	    }
